# ── Put one investment's facts together from its documents, and have AI write the family-friendly overview ──
import json
import re
from collections import Counter

MAX_SNIPPETS = 10

WRITE_PROMPT = (
    "You are writing the overview on a one-page investment summary for members of a family who have no prior "
    "knowledge of this investment. Use only the facts and notes given. Write in plain, warm, factual English, "
    "Australian spelling, no jargon, no advice, no hype. business: what the company does and who its customers "
    "are (at most 50 words). investment: what the family holds, when and for how much (at most 45 words). "
    "rationale: why the family invested, as the notes say (at most 45 words); if the notes don't say, write what "
    "the documents show about the opportunity at the time, without guessing. milestones: pick the 5 most "
    "meaningful dated events from the candidates, oldest first, each at most 8 words, keeping the given dates."
)
WRITE_SHAPE = '{"business": str, "investment": str, "rationale": str, "milestones": [{"date": "YYYY-MM-DD", "text": str}]}'


def _common(values):
    vals = [v for v in values if v]
    return Counter(vals).most_common(1)[0][0] if vals else ""


def _latest(docs, key):
    """The value from the most recent document that states it."""
    best = None
    for d in docs:
        if d.get(key) not in (None, "", "unknown") and (best is None or (d.get("doc_date") or "") >= (best.get("doc_date") or "")):
            best = d
    return best.get(key) if best else None


def _mkey(date, text):
    return date[:7] + re.sub(r"[^a-z]", "", text.lower())[:24]


docs = params.get("docs") or []
files = params.get("files") or []
problem = str(params.get("problem") or "")
facts = {}

if docs and not problem:
    company = _common(d.get("company") for d in docs) or str(params.get("investment_name") or "") or \
        str(params.get("folder_name") or "")

    # Money invested: each subscription or purchase once, even when several documents mention it
    tranches = {}
    for d in docs:
        t = d.get("new_investment")
        if t:
            tranches.setdefault((t["date"], round(t["amount"])), t)
    tranches = sorted(tranches.values(), key=lambda t: t["date"])

    # Dividends: each payment once, from the dividend statements
    paid = {}
    for d in docs:
        for x in d.get("dividends") or []:
            paid.setdefault((x["date"], round(x["amount"], 2)), x)
    dividends = sorted(paid.values(), key=lambda x: x["date"])
    # Year totals (tax statements) fill in years with no individual statements
    year_totals = {}
    for d in docs:
        for y in d.get("dividend_year_totals") or []:
            year_totals[y["year_ending"]] = y["amount"]

    valuations = sorted([d["valuation"] for d in docs if d.get("valuation")], key=lambda v: v["date"])

    milestones = {}
    for d in docs:
        for m in d.get("milestones") or []:
            milestones.setdefault(_mkey(m["date"], m["text"]), m)
    # The investment and the first dividend, unless a document already marks that month
    months = {m["date"][:7] for m in milestones.values()}
    if tranches and tranches[0]["date"][:7] not in months:
        milestones["inv"] = {"date": tranches[0]["date"], "text": "Investment made"}
    if dividends and dividends[0]["date"][:7] not in months:
        milestones["div1"] = {"date": dividends[0]["date"], "text": "First dividend paid"}
    candidates = sorted(milestones.values(), key=lambda m: m["date"])[:40]

    def snippets(key):
        seen = []
        for d in sorted(docs, key=lambda d: d.get("doc_date") or "", reverse=True):
            s = d.get(key)
            if s and s not in seen:
                seen.append(s)
        return seen[:MAX_SNIPPETS]

    facts = {
        "company": company,
        "holder": _common(d.get("holder") for d in docs),
        "instrument": _latest(docs, "instrument") or "",
        "shares": _latest(docs, "shares"),
        "price_per_share": _common(d.get("price_per_share") for d in docs if d.get("price_per_share")) or None,
        "ownership_pct": _latest(docs, "ownership_pct"),
        "website": _common(d.get("website") for d in docs),
        "board": _latest(docs, "board") or "",
        "status": _latest(docs, "status") or "",
        "tranches": tranches,
        "dividends": dividends,
        "year_totals": year_totals,
        "valuation": valuations[-1] if valuations else None,
        "milestones": candidates[:5],
        "business": "",
        "investment": "",
        "rationale": "",
    }

    brief = {k: facts[k] for k in ("company", "holder", "instrument", "shares", "ownership_pct", "tranches",
                                   "valuation", "status", "website")}
    brief["dividends_received"] = {"payments": len(dividends), "total": round(sum(x["amount"] for x in dividends), 2)}
    brief["notes_on_business"] = snippets("business")
    brief["notes_on_investment"] = snippets("investment")
    brief["notes_on_rationale"] = snippets("rationale")
    brief["milestone_candidates"] = candidates
    try:
        w = api.ai.extract(prompt=WRITE_PROMPT, input=json.dumps(brief)[:28000], schema_hint=WRITE_SHAPE)
    except Exception:
        w = {}
    w = w if isinstance(w, dict) else {}
    for k in ("business", "investment", "rationale"):
        facts[k] = re.sub(r"\s+", " ", str(w.get(k) or "")).strip() or (snippets(k)[:1] or [""])[0]
    picked = [m for m in (w.get("milestones") or [])
              if isinstance(m, dict) and re.match(r"^\d{4}-\d{2}-\d{2}$", str(m.get("date") or "")) and m.get("text")]
    if picked:
        facts["milestones"] = sorted([{"date": m["date"], "text": str(m["text"])[:60]} for m in picked],
                                     key=lambda m: m["date"])[:5]

summary = problem or ("Put together " + (facts.get("company") or "the investment") + " from " + str(len(docs)) +
                      " documents: " + str(len(facts.get("dividends") or [])) + " dividend payments, " +
                      str(len(facts.get("tranches") or [])) + " investment(s).")

# ── Find the investment's receipts in the Xero bank accounts and compare them with the dividend statements ──
import re
from datetime import datetime, timezone

XERO = "xero-accounting"
MAX_PAGES = 30
# Words that don't identify a company on their own
GENERIC = {"pty", "ltd", "limited", "proprietary", "holdings", "group", "the", "and", "co", "company", "inc",
           "trust", "trustee", "for", "investments", "australia", "australian"}


def _err(exc):
    msg = str(exc)
    if msg.startswith("tool_error: "):
        msg = msg[len("tool_error: "):]
    if "no usable credential" in msg or "credential unavailable" in msg:
        return "the Xero connection needs connecting (Settings → Connections → xero-accounting)"
    return msg[:200]


def _xero_date(v):
    s = str(v or "")
    m = re.search(r"/Date\((\d+)", s)
    if m:
        return datetime.fromtimestamp(int(m.group(1)) / 1000, tz=timezone.utc).strftime("%Y-%m-%d")
    return s[:10] if re.match(r"^\d{4}-\d{2}-\d{2}", s) else ""


def _terms(facts, extra):
    if extra.strip():
        return [t.strip().lower() for t in extra.split(",") if t.strip()]
    words = [w for w in re.findall(r"[a-z0-9&']+", str(facts.get("company") or "").lower()) if w not in GENERIC]
    # The first two distinctive words together ("greenfield cold"), so a common word alone doesn't match
    return [" ".join(words[:2])] if words else []


def _fy(date):
    return int(date[:4]) + (1 if int(date[5:7]) >= 7 else 0)


facts = params.get("facts") or {}
extra = str(params.get("xero_match") or "")
xero = {"checked": False, "receipts": [], "total": 0.0, "note": "", "terms": []}

terms = _terms(facts, extra)
xero["terms"] = terms
start = (facts.get("tranches") or [{}])[0].get("date") or ""
if not facts:
    xero["note"] = ""
elif not terms:
    xero["note"] = "Xero not checked: no company name to look for."
else:
    where = 'Type=="RECEIVE"&&Status=="AUTHORISED"'
    if start:
        where += "&&Date>=DateTime(" + ",".join(str(int(x)) for x in start.split("-")) + ")"
    found = []
    try:
        for page in range(1, MAX_PAGES + 1):
            res = api.connectors.invoke(server=XERO, tool="list_bank_transactions",
                                        args={"where": where, "order": "Date", "page": page})
            batch = (res or {}).get("BankTransactions") or [] if isinstance(res, dict) else []
            for t in batch:
                lines = t.get("LineItems") or []
                text = " ".join([str((t.get("Contact") or {}).get("Name") or ""), str(t.get("Reference") or "")] +
                                [str(li.get("Description") or "") for li in lines]).lower()
                if any(term in text for term in terms):
                    found.append({
                        "date": _xero_date(t.get("Date")),
                        "amount": round(float(t.get("Total") or 0), 2),
                        "contact": str((t.get("Contact") or {}).get("Name") or ""),
                        "reference": str(t.get("Reference") or "")[:80],
                        "account": str((t.get("BankAccount") or {}).get("Name") or ""),
                    })
            if len(batch) < 100:
                break
        xero["checked"] = True
    except Exception as exc:
        xero["note"] = "Xero not checked: " + _err(exc) + "."

    if xero["checked"]:
        found = [r for r in found if r["date"]]
        xero["receipts"] = found
        xero["total"] = round(sum(r["amount"] for r in found), 2)
        statements = facts.get("dividends") or []
        stated = round(sum(x["amount"] for x in statements), 2)
        label = " or ".join('"' + t + '"' for t in terms)
        if not found:
            xero["note"] = "Xero check: no bank receipts mention " + label + "."
        elif not statements:
            xero["note"] = ("Xero check: " + str(len(found)) + " bank receipts mention " + label +
                            "; there are no dividend statements to compare them with.")
        elif abs(xero["total"] - stated) < 1:
            xero["note"] = ("Xero check: the " + str(len(found)) + " bank receipts match the dividend statements (A$" +
                            format(xero["total"], ",.2f") + ").")
        else:
            by_fy = {}
            for x in statements:
                by_fy[_fy(x["date"])] = by_fy.get(_fy(x["date"]), 0) + x["amount"]
            for r in found:
                by_fy[_fy(r["date"])] = by_fy.get(_fy(r["date"]), 0) - r["amount"]
            off = ["FY" + str(y)[2:] for y, v in sorted(by_fy.items()) if abs(v) >= 1]
            xero["note"] = ("Xero check: bank receipts total A$" + format(xero["total"], ",.2f") + " against A$" +
                            format(stated, ",.2f") + " in the dividend statements" +
                            ((" (differs in " + ", ".join(off[:6]) + ")") if off else "") + ".")

summary = xero["note"] or "Xero not checked."
